function category(p){const t=p.raw_properties||p, a=String(t.amenity||p.amenity||'').toLowerCase(),shop=String(t.shop||''),tourism=String(t.tourism||''),leisure=String(t.leisure||''),c=String(p.category||p.category_from_source||'').toLowerCase();
if(a==='restaurant')return 'restaurant';if(a==='cafe')return 'cafe';if(['fast_food','food_court','bar','pub'].includes(a))return 'fast_food';
if(['supermarket','convenience','mall'].includes(shop))return 'supermarket';if(shop)return 'retail';
if(a==='pharmacy'||/аптек|pharmacy/.test(c))return 'pharmacy';if(['hospital','clinic','doctors','dentist'].includes(a)||/лікар|мед|hospital|clinic|doctors/.test(c))return 'hospital';
if(['bank','atm'].includes(a))return 'bank';if(['hotel','hostel','guest_house'].includes(tourism))return 'hotel';if(['park','playground','garden','sports_centre'].includes(leisure))return 'park';
if(['cinema','theatre','arts_centre'].includes(a)||['museum','attraction'].includes(tourism))return 'culture';if(a==='toilets')return 'toilets';
if(['library','school','university','college','kindergarten'].includes(a)||/школ|університет|освіт|school|university|college|kindergarten/.test(c))return 'education';
if(t.highway==='bus_stop'||t.public_transport||/зупин|транспорт|bus|tram|rail|station|stop/.test(c))return 'transport';
if(['townhall','post_office','police','community_centre','social_facility'].includes(a)||t.office||/цнап|адміністр|держ|public|office|government|civic|соціальн/.test(c))return 'public';
if(/магаз|shop|supermarket|market|комерц|торгов/.test(c))return 'retail';if(/restaurant|ресторан/.test(c))return 'restaurant';if(/cafe|кафе/.test(c))return 'cafe';return 'other'}

function flag(val){if(val===true)return 'yes';if(val===false)return 'no';let s=String(val??'').trim().toLowerCase();if(['yes','true','1','так','є','наявний','наявна','designated'].includes(s))return 'yes';if(['no','false','0','ні','немає','відсутній','відсутня'].includes(s))return 'no';if(['limited','partial','частково'].includes(s))return 'partial';return 'unknown'}
function parsePlace(feature,index){if(!feature||feature.type!=='Feature'||feature.geometry?.type!=='Point')return null;const [lon,lat]=feature.geometry.coordinates||[];if(!Number.isFinite(+lat)||!Number.isFinite(+lon)||lat<BOUNDS.s||lat>BOUNDS.n||lon<BOUNDS.w||lon>BOUNDS.e)return null;const p=feature.properties||{};const raw=p.raw_properties&&typeof p.raw_properties==='object'?p.raw_properties:p;
  const nm=p.name||raw['name:uk']||raw.name||p.title||p.назва;
  if(!nm||!String(nm).trim())return null;
  let id=String(p.id||feature.id||`${p.source_id||'file'}:${p.source_record_id||p.osm_id||JSON.stringify([String(nm).trim(),+lon,+lat])}`);
  if(/^(node|way|relation)\/\d+$/.test(id))id='openstreetmap:'+id;
  const source=(p.source_id==='openstreetmap'||id.startsWith('openstreetmap:'))?'OpenStreetMap':p.source_id||'Відкриті дані';
  return {id,name:String(nm),lat:+lat,lon:+lon,category:category({...p,raw_properties:raw}),address:p.address||raw['addr:full']||[raw['addr:street'],raw['addr:housenumber']].filter(Boolean).join(', ')||p.адреса||'',source,sourceUrl:safeUrl(p.source_url)||(id.startsWith('openstreetmap:')?'https://www.openstreetmap.org/'+id.slice(14):null),sourceDate:p.source_date||p.dataset_updated_at||null,observedAt:p.observed_at||null,qualities:{wheelchair:flag(p.wheelchair??raw.wheelchair),ramp:flag(p.ramp??raw.ramp),entrance:flag(p.accessible_entrance??raw['entrance:wheelchair']),toilet:flag(p.accessible_toilet??raw['toilets:wheelchair']),stairs:flag(p.stairs??raw.stairs),elevator:flag(p.elevator??raw.elevator)},conflicts:Object.keys({wheelchair:1,ramp:1,stairs:1}).filter(k=>p.raw_properties&&p[k]!=null&&raw[k]!=null&&flag(p[k])!=='unknown'&&flag(raw[k])!=='unknown'&&flag(p[k])!==flag(raw[k])),raw:p};
}
function parseGeoJSON(doc){if(!doc||doc.type!=='FeatureCollection'||!Array.isArray(doc.features))throw Error('Потрібний GeoJSON типу FeatureCollection.');const points=[],barriers=[];doc.features.forEach((f,i)=>{if(f?.geometry?.type!=='Point')return;const p=f.properties||{}, raw=p.raw_properties||{}, tag=raw.highway||p.highway;if(tag==='steps'||p.kind==='barrier'||(p.barrier_type&&p.source_id==='openstreetmap')){const coords=f.geometry.coordinates||[];if(Number.isFinite(+coords[0])&&Number.isFinite(+coords[1]))barriers.push({id:`barrier-${i}`,lat:+coords[1],lon:+coords[0],label:p.name||'Зафіксована перешкода',source:p.source_id||'Набір даних'});return}let v=parsePlace(f,i);if(v)points.push(v)});return {places:points,barriers}}
function combine(){const index=new Map();const items=state.demo?[parsePlace({type:'Feature',geometry:{type:'Point',coordinates:[25.937,48.292]},properties:{name:'ДЕМО · Умовний заклад',source_id:'Демонстраційні дані',source_record_id:'sample'}},0)]:[...state.places,...state.snapshot,...state.imported,...state.osm];for(const p of items)index.set(p.id,p);state.current=[...index.values()].sort((a,b)=>a.name.localeCompare(b.name,'uk'))}
function statusFor(p){const q=p.qualities;if(p.conflicts?.length)return {key:'conflict',text:'Суперечливі дані'};if(q.stairs==='yes'||q.wheelchair==='no'||q.entrance==='no')return {key:'bad',text:'Вказано бар’єр'};if(q.wheelchair==='yes')return {key:'good',text:'Доступність за даними джерела'};if(q.wheelchair==='partial'||q.ramp==='partial'||q.entrance==='partial')return {key:'partial',text:'Частково'};return {key:'unknown',text:'Немає даних'}}
function suitability(p){const q=p.qualities, unknown=[],problem=[];if(state.needs.entrance){if(q.wheelchair==='no'||q.entrance==='no')problem.push('вхід');else if(q.wheelchair!=='yes'&&q.entrance!=='yes')unknown.push('вхід');}if(state.needs.steps){if(q.stairs==='yes')problem.push('сходи');else if(q.stairs!=='no')unknown.push('сходи');}if(state.needs.kerbs)unknown.push('бордюри');if(state.needs.slopes)unknown.push('ухил');return {problem,unknown}}
const filtered=()=>{let out=(state.current||[]).filter(p=>catMatches(p,state.cat)&&(state.accessFilter==='all'||statusFor(p).key===state.accessFilter));const term=state.search.trim().toLocaleLowerCase('uk');if(term)out=out.filter(p=>[p.name,p.address,catInfo(p.category)?.name||''].join(' ').toLocaleLowerCase('uk').includes(term));if(state.tab==='saved')out=out.filter(p=>state.saved.includes(p.id));const rank=p=>{const s=statusFor(p).key, suit=suitability(p);return suit.problem.length?4:s==='conflict'?3:s==='good'?0:s==='partial'?1:s==='unknown'?2:4};return out.sort((a,b)=>rank(a)-rank(b)||a.name.localeCompare(b.name,'uk'))};
function updateHeader(){const count=(state.current||[]).length;$('#dataHeader').textContent=count?`${count} об’єктів`:'Дані ще не завантажені';$('.live-indicator').classList.toggle('active',count>0);$('#mapInfo').innerHTML=`<span class="tip-mark"></span>${count?`${count} записів із джерел · доступність потребує перевірки`:'Немає завантажених місцевих записів'}`;}
