function setTab(tab){state.lastOrigin='';state.chooseDestination=false;state.tab=tab;state.page='home';state.selectedId=null;$$('.nav-btn').forEach(n=>{const on=n.dataset.tab===tab;n.classList.toggle('active',on);if(on)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});$('#panel').classList.toggle('expanded',tab!=='map');render();}
function setTitle(title,subtitle,back){$('#panelTitle').textContent=title;$('#panelSubtitle').textContent=subtitle;$('#backButton').classList.toggle('hidden',!back)}
